const excludedDomains = [
  'gmail.com',       // Google
  'outlook.com',     // Microsoft
  'yahoo.com',       // Yahoo
  'titan.email',     // Titan
  'icloud.com',      // Apple
  'hotmail.com',     // Microsoft
  'aol.com',         // AOL
  'zoho.com',        // Zoho Mail
  'protonmail.com',  // ProtonMail
  'mail.com',        // Mail.com
];

const filteredData = [];
for (let item of items) {
  const domain = item.json.domain;  // Accessing the domain field
  if (!excludedDomains.includes(domain)) {
    filteredData.push(item);  // Only push if the domain is NOT in the excluded list
  }
}

return filteredData;

// This gets the incoming items from the previous node
const items = $input.all();  // Fetch all items from the previous node

// Function to clean the content by removing markdown and unwanted elements
function cleanContent(content) {
  // Example: Removing markdown image syntax, excessive newlines, and trimming the content
  return content
    .replace(/!\[.*?\]\(.*?\)/g, '')  // Removes markdown images
    .replace(/\n+/g, '\n')            // Replaces multiple newlines with a single newline
    .trim();                          // Trims any leading or trailing spaces
}

// Initialize an array to store the cleaned data
let returnData = [];

// Process each item dynamically based on the input from the previous node
for (let i = 0; i < items.length; i++) {
  const content = items[i].json.content || '';         // Get content, fallback to empty string if undefined
  const description = items[i].json.description || ''; // Get description, fallback to empty string if undefined

  const cleanedContent = cleanContent(content);  // Clean the content

  // Push the cleaned content and description into the return data array
  returnData.push({
    json: {
      cleanedContent: cleanedContent,
      description: description
    }
  });
}

// Return the cleaned data to n8n
return returnData;

// This gets the incoming items from the previous node
const items = $input.all();  // Fetch all items from the previous node

// Function to clean the content and extract only the relevant information from experiences
function extractExperienceDetails(experience) {
  const title = experience.title || 'Unknown Role';
  const company = experience.company || 'Unknown Company';
  const startYear = experience.start_year || 'Unknown Start Year';
  const endYear = experience.is_current ? 'Present' : (experience.end_year || 'Unknown End Year');  // Handles current roles
  const duration = experience.duration || '';

  return `${title} at ${company} (${startYear} - ${endYear}) - ${duration}`.trim();
}

// Initialize an array to store the cleaned data
let returnData = [];

// Process each item dynamically based on the input from the previous node
for (let i = 0; i < items.length; i++) {
  const data = items[i].json.data || {};  // Get the main data object from the item, fallback to an empty object if undefined
  const about = data.about || '';         // Get the 'about' section content, fallback to an empty string if undefined
  const headline = data.headline || '';   // Get the headline content, fallback to an empty string if undefined
  const experiences = data.experiences || [];  // Get the experiences array, fallback to an empty array if undefined

  // Clean the content from 'about' and 'headline' sections
  const cleanedAbout = about.replace(/\n+/g, ' ').trim();
  const cleanedHeadline = headline.replace(/\n+/g, ' ').trim();

  // Clean and extract key details (role, company, years) from each experience
  let cleanedExperiences = experiences.map(exp => extractExperienceDetails(exp));

  // Identify the current position (if any), using "-present" in the experience
  let currentPosition = null;
  for (let exp of experiences) {
    if (exp.is_current) {
      const title = exp.title || 'Unknown Role';
      const company = exp.company || 'Unknown Company';
      const startYear = exp.start_year || 'Unknown Start Year';
      currentPosition = `${title} at ${company} (${startYear} - Present)`;
      break;  // Assuming only one current position, so we can exit after finding it
    }
  }

  // Push the cleaned content into the return data array inside the 'response' -> 'scraped_linkedin_info' field
  returnData.push({
    json: {
      response: {
        scraped_linkedin_info: {
          cleanedAbout: cleanedAbout,
          cleanedHeadline: cleanedHeadline,
          cleanedExperiences: cleanedExperiences,
          currentPosition: currentPosition // Add current position information
        }
      }
    }
  });
}

// Return the cleaned data to n8n
return returnData;

